INSERT INTO "goods" VALUES (10029, 0, 1, 1744619635, 0, 100, 1, 2, 0, 99, 0, 1, ',10029,', '', '早餐', '', 0.0, 1, 0.0, 0.0, 0.0, 'data/file/goods/10029', '', '', '', NULL, '', '', '');
INSERT INTO "goods" VALUES (10030, 0, 1, 1744619653, 0, 100, 1, 2, 0, 99, 0, 1, ',10030,', '', '中餐', '', 0.0, 1, 0.0, 0.0, 0.0, 'data/file/goods/10030', '', '', '', NULL, '', '', '');
INSERT INTO "goods" VALUES (10031, 0, 1, 1744619662, 0, 100, 1, 2, 0, 99, 0, 1, ',10031,', '', '晚餐', '', 0.0, 1, 0.0, 0.0, 0.0, 'data/file/goods/10031', '', '', '', NULL, '', '', '');
INSERT INTO "goods" VALUES (10032, 10030, 1, 1744619669, 1774602277, 102, 1, 1, 0, 792, 6, 3, ',10030,10032,', '', '烤鱼配时令蔬菜', '', 0.01, 4, 7.0, 786.0, 0.0, 'data/file/goods/10032', '', '1.webp', '', NULL, '', '金黄酥脆的烤鱼为主体，搭配新鲜时令蔬菜，色彩鲜艳，口感丰富。精致的摆盘和点缀更是为其增添了艺术感，是一道兼具美味与视觉享受的佳肴。', '<p>品味精致，享受每一口的美妙</p>
<p>在这繁忙的都市生活中，偶尔停下来，享受一顿精致的美食，是一种难得的奢侈。今天，为大家介绍一道不仅视觉上令人惊艳，更是味蕾上的极致享受的菜品。</p>
<p>这道菜品以其精美的摆盘和丰富的口感，完美地诠释了什么是高级餐饮的魅力。洁白的盘子上，点缀着粉色的酱点，仿佛一幅艺术品。主菜选用了新鲜的鱼肉，经过精心的烹饪，外皮酥脆，内里鲜嫩多汁，搭配上烤制的蔬菜，色彩鲜艳，营养均衡。</p>
<p>旁边的红色蔬菜沙拉，不仅为整道菜增添了色彩，还带来了清爽的口感。而那碗精致的酱汁，更是点睛之笔，浓郁的香气和丰富的层次感，让每一口都充满了惊喜。</p>
<p>无论是商务宴请，还是浪漫晚餐，这道菜品都能为您带来无与伦比的用餐体验。让我们一起品味这份精致，享受每一口的美妙吧！</p>');
INSERT INTO "goods" VALUES (10033, 10030, 1, 1744619764, 1751536939, 100, 1, 1, 0, 99, 0, 1, ',10030,10033,', '', '金香田园饭', '', 32.0, 1, 0.0, 0.0, 0.0, 'data/file/goods/10033', '', '2.webp', '', NULL, '', '新鲜的黄瓜片和番茄片不仅增添了色彩，还提供了清爽的口感。整体呈现出田园般的宁静与舒适，是一道令人愉悦的美食选择。', '');
INSERT INTO "goods" VALUES (10034, 10029, 1, 1744620004, 1751536899, 100, 1, 1, 0, 99, 0, 1, ',10029,10034,', '', '彩椒包裹美味卷', '', 15.0, 1, 0.0, 0.0, 0.0, 'data/file/goods/10034', '', '3.webp', '', NULL, '', '色彩鲜艳的彩椒为点缀，搭配精心包裹的美味卷，呈现出视觉与味觉的双重享受。卷内含有丰富的蔬菜和调料，口感层次丰富，健康美味兼具。', '');
INSERT INTO "goods" VALUES (10035, 10029, 1, 1744676702, 1753864888, 100, 1, 1, 0, 99, 0, 1, ',10029,10035,', '', '阳光早餐', '', 43.0, 2, 0.0, 0.0, 0.0, 'data/file/goods/10035', '', '4.webp', '', NULL, '', '煎蛋、新鲜番茄和法式面包为主，简单易做，营养丰富，为一天的开始注入满满的能量和愉悦感。', '');
INSERT INTO "goods" VALUES (10036, 10031, 1, 1744706860, 1751536849, 100, 1, 1, 0, 99, 0, 1, ',10031,10036,', '', '奶油虾仁意大利面', '', 54.0, 1, 0.0, 0.0, 0.0, 'data/file/goods/10036', '', '5.webp', '', NULL, '', '奶油虾仁意大利面以其浓郁的奶油酱汁和鲜美的虾仁为特色，搭配精致的摆盘，带来视觉和味觉的双重享受。无论是作为主菜还是特别晚餐，这道菜都能展现出品位与美味。', '');
INSERT INTO "goods" VALUES (10037, 10031, 1, 1744763706, 1751536778, 100, 1, 1, 0, 99, 0, 1, ',10031,10037,', '', '香煎鸡胸配藜麦沙拉', '', 66.0, 1, 0.0, 0.0, 0.0, 'data/file/goods/10037', '', '6.webp', '', NULL, '', '香煎鸡胸肉、藜麦和新鲜蔬菜，色彩鲜艳，营养丰富。香煎鸡胸肉肉质鲜嫩，藜麦口感独特，搭配黄瓜和香菜，既美味又健康，是一道适合各种场合的理想菜肴。', '');
INSERT INTO "goods" VALUES (10038, 10031, 1, 1744763768, 1751536714, 100, 1, 1, 0, 99, 0, 1, ',10031,10038,', '', '秋日南瓜绿叶沙拉', '', 69.0, 1, 0.0, 0.0, 0.0, 'data/file/goods/10038', '', '7.webp', '', NULL, '', '秋日南瓜绿叶沙拉以新鲜的绿叶蔬菜和香甜的南瓜为主要食材，搭配坚果和种子，口感丰富，营养均衡，是一道美味又健康的秋季佳肴。', '');
INSERT INTO "goods" VALUES (10039, 10029, 1, 1744763825, 1751537051, 99, 1, 1, 0, 99, 0, 1, ',10029,10039,', '', '面包、土豆、煎蛋与肉饼', '', 26.0, 1, 0.0, 0.0, 0.0, 'data/file/goods/10039', '', '8.webp', '', NULL, '', '新鲜的面包、香脆的土豆、嫩滑的煎蛋和美味的肉饼，构成了一份营养丰富、口感多样的丰盛早餐，适合开启美好的一天。', '');
INSERT INTO "goods" VALUES (10040, 10030, 1, 1744763953, 1751536692, 100, 1, 1, 0, 99, 0, 1, ',10030,10040,', '', '彩缤纷蛋香饭', '', 58.0, 1, 0.0, 0.0, 0.0, 'data/file/goods/10040', '', '9.webp', '', NULL, '', '米饭的绵软搭配上煮鸡蛋的鲜嫩、番茄的酸甜、洋葱的清香以及芝麻的点缀，使得每一口都充满层次感。', '');
INSERT INTO "goods" VALUES (10041, 10030, 1, 1744764052, 1751536672, 100, 1, 1, 0, 99, 0, 1, ',10030,10041,', '', '芝麻贝果配新鲜菠菜', '', 25.0, 1, 0.0, 0.0, 0.0, 'data/file/goods/10041', '', '10.webp', '', NULL, '', '撒满芝麻的贝果、奶酪和新鲜菠菜组成，搭配适量的粉状调料，既美味又营养，是一道理想的早餐或轻食选择。', '');
INSERT INTO "goods" VALUES (10042, 10029, 1, 1744764138, 1752111714, 100, 1, 1, 0, 98, 1, 1, ',10029,10042,', '', '粉红晨曦', '', 22.0, 5, 0.0, 0.0, 0.0, 'data/file/goods/10042', '', '11.webp', '', NULL, '', '粉红色调和精致的摆盘，营造出一种晨曦般的温馨氛围。新鲜的食材和独特的酱料相结合，带来一份既美观又美味的早餐，让你在清晨就能感受到生活的美好与惊喜。', '');
INSERT INTO "goods" VALUES (10043, 10031, 1, 1744764327, 1751536618, 101, 1, 1, 0, 99, 0, 1, ',10031,10043,', '', '香烤肉串配时蔬', '', 99.98, 2, 0.0, 0.0, 0.0, 'data/file/goods/10043', '', '12.webp', '', NULL, '', '香烤肉串为主，搭配新鲜的时令蔬菜，色彩丰富，口感层次分明。肉串外焦里嫩，蔬菜清爽可口，完美结合了美味与健康。', '');
INSERT INTO "goods" VALUES (10044, 10030, 1, 1744764412, 1751536581, 101, 1, 1, 0, 98, 1, 1, ',10030,10044,', '', '奶油蘑菇鸡肉配米饭', '', 0.0, 3, 0.0, 0.0, 0.0, 'data/file/goods/10044', '', '13.webp', '', NULL, '', '嫩滑的鸡肉、浓郁的奶油蘑菇酱和香软的米饭组成，色香味俱佳，令人垂涎欲滴。奶油蘑菇酱的丰富口感与鸡肉的鲜美完美结合，搭配上细腻的米饭，带来一场味蕾的盛宴。', '');
INSERT INTO "goods" VALUES (10045, 10030, 1, 1744764621, 1753864867, 99, 1, 1, 0, 99, 0, 1, ',10030,10045,', '', '金黄煎鱼配芒果沙拉', '', 45.0, 5, 0.0, 0.0, 0.0, 'data/file/goods/10045', '', '15.webp', '', NULL, '', '金黄煎鱼为主角，搭配鲜美的芒果沙拉，色彩鲜艳，口感丰富。精致的摆盘和细腻的调味，使每一口都充满层次感和惊喜，是一道令人难以忘怀的精致料理。', '');
INSERT INTO "goods" VALUES (10046, 10031, 1, 1744764739, 1751536989, 99, 1, 1, 0, 99, 0, 1, ',10031,10046,', '', '烟熏三文鱼拼盘', '', 48.0, 1, 0.0, 0.0, 0.0, 'data/file/goods/10046', '', '14.webp', '', NULL, '', '烟熏三文鱼拼盘以其新鲜的食材和精美的摆盘而著称。三文鱼片搭配紫洋葱圈、酸豆、柠檬片，配以清爽的黄瓜片和番茄片，呈现出色彩丰富、口感多样的美食体验。无论是作为早餐还是轻食，这道拼盘都能带给您视觉和味觉的双重享受。', '');
INSERT INTO "goods" VALUES (10047, 10031, 1, 1744764821, 1751536491, 101, 1, 1, 0, 98, 1, 2, ',10031,10047,', '', '缤纷寿司盛宴', '', 58.0, 1, 0.0, 0.0, 0.0, 'data/file/goods/10047', '', '16.webp', '', NULL, '', '拼盘汇集了多种经典的日式寿司，色彩鲜艳，口感丰富。每一口都能感受到新鲜食材的美味，搭配酱油，更是让人回味无穷。无论是作为一顿精致的晚餐，还是与朋友分享的美食时光，这道寿司拼盘都能带来愉悦的味蕾体验。', '');
INSERT INTO "goods" VALUES (10063, 10031, 1, 1750041363, 1767583820, 132, 1, 1, 0, 773, 1, 3, ',10031,10063,', '', '超高速多功能适配器 35W', '', 199.99, 2, 0.1, 199.99, 0.0, 'data/file/goods/10063', '', '2.webp', '', NULL, '', '', '<p>Hello, world!是大家第一次学习Programming时最常写的demo，它看似简单，但对有些人来说寥寥数语有时也会产生bug。</p>
<p>古代称用以书写的小幅绢帛。后亦以借指纸。《汉书·外戚传下·孝成赵皇后》：「武（籍武 ）发篋中，有裹药二枚，赫蹏书。」颜师古注：「邓展曰：『赫音兄弟鬩墙之鬩。』应劭曰：『赫蹏，薄小纸也。』」宋赵彦卫《云麓漫钞》卷七：「《赵后传》所谓『赫蹏』者，注云『薄小纸』，然其寔亦縑帛。」</p>
<p><span style="font-size: 1rem; color: #000000; font-family: ''Helvetica Neue'', helvetica, arial, ''Heti Hei'', sans-serif, ''Apple Color Emoji'', ''Segoe UI Emoji'', ''Segoe UI Symbol''; letter-spacing: 0.32px;"><img src="data/file/shop/banner.jpg" alt="" /></span></p>');
INSERT INTO "goods" VALUES (10072, 10031, 1, 1753930110, 1757665094, 132, 1, 1, 0, 221, 0, 1, ',10031,10072,', '', '纯洁美旅行款淋浴器', '', 99999.99, 2, 0.0, 0.0, 0.0, 'data/file/goods/10072', '', '1.webp', '', NULL, '', '金黄酥脆的烤鱼为主体，搭配新鲜时令蔬菜，色彩鲜艳，口感丰富。', '');
INSERT INTO "goods" VALUES (10084, 0, 1, 1757664029, 0, 0, 0, 1, 0, 99, 0, 1, '', '', '重命名标题', '', 0.0, 1, 0.0, 0.0, 0.0, '', '', '', '', NULL, '', '', '');
INSERT INTO "goods" VALUES (10097, 10029, 1, 1757925200, 1757925283, 133, 0, 1, 0, 99, 0, 1, ',10029,10097,', '', '玉露冻奶茶', '', 52.0, 1, 0.0, 0.0, 0.0, 'data/file/goods/10097', '', '_.jpg', '', NULL, '', '经典红茶和奶香完美融合，搭配上自制绿茶冻，增添咀嚼口感。', '');
