INSERT INTO "item" VALUES (10002, 10022, 0, 7, 1632965620, 1757579348, 102, 1, 1, 'c935901b3789b3c90c7f72448a7cbb48', ',10022,10002,', '', '白露——温差最大的时节2', '', NULL, '', 'data/file/item/10002', '', '7.webp', '', '', '', '', '', '', '{"url":"","target":"_blank"}', '{"title":"","keywords":"","description":""}', '白露时节，是一年中温差最大的时节，夏季风和冬季风将在这里激烈地邂逅，说不清谁痴迷谁，谁又留恋谁，只有难舍难分的纠缠。', '&lt;p&gt;&lt;img src=&quot;data/file/shop/banner.jpg&quot; alt=&quot;&quot; /&gt;&lt;/p&gt;
&lt;p&gt;白露时节，是一年中温差最大的时节，夏季风和冬季风将在这里激烈地邂逅，说不清谁痴迷谁，谁又留恋谁，只有难舍难分的纠缠。白露临近中秋，自然容易勾起人的无限离情。白露，注定是思乡的。白露含秋，滴落三千年的乡愁。&lt;/p&gt;
&lt;p&gt;&lt;a href=&quot;data/file/1743040247526.json&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot; download=&quot;data/file/1743040247526.json&quot;&gt;&lt;img src=&quot;data/file/blog/01.png&quot; alt=&quot;&quot; /&gt;附件&lt;/a&gt;&lt;/p&gt;
&lt;p&gt;&lt;span style=&quot;font-size: 14px; color: #999999;&quot;&gt;&lt;em&gt;白露气象和农事特点：天高气爽，千家万户忙秋收、秋种。&lt;/em&gt;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;天高气爽，云淡风轻。阳历9月8日前后，太阳黄经为165&amp;deg;就是白露节气。白露时节，全国大部分地区天高气爽，云淡风轻，气温渐凉、晚上草木上可以见到白色露水。露水是由于温度降低，水汽在地面或近地物体上凝结而成的水珠。此时，天气转凉，地面水汽结露最多。所以，白露实际上是表示天气已经转凉。&lt;/p&gt;
&lt;p&gt;一个春夏的辛勤劳作，经历了风风雨雨，送走了高温酷暑，迎来了气候宜人的收获季节。俗话说：&amp;ldquo;白露秋分夜，一夜冷一夜。&amp;rdquo;这个时节夏季风逐渐被冬季风所接管，多吹偏北风，冷空气南下逐渐频繁，加上太阳直射地面的位置南移，北半球日照时间变短，日照强度减弱，夜间常晴朗少云，地面辐射散热快，因此温度下降也逐渐加速。&lt;/p&gt;', '{"content_type":"html"}');
