INSERT INTO "item" VALUES (10018, 0, 0, 7, 1633679826, 1752478781, 101, 1, 1, '3a97b13caae23fcc880cfbb000da5c9b', ',10018,', '', '秋色平分，碧空万里', '', NULL, '', 'data/file/item/10018', '', '5.webp', '', '', '', '', '', '', '{"url":"","target":"_blank"}', '{"title":"","keywords":"","description":""}', '秋分是美好宜人的时节，秋高气爽，丹桂飘香，蟹肥菊黄。秋分平分秋色，万山红遍，层林尽染。', '&lt;p&gt;秋分是美好宜人的时节，秋高气爽，丹桂飘香，蟹肥菊黄。秋分平分秋色，万山红遍，层林尽染。秋分带走初秋的淡雅，迎来深秋的斑斓。&lt;/p&gt;
&lt;p&gt;&lt;img src=&quot;data/file/blog/02.png&quot; alt=&quot;&quot; /&gt;&lt;/p&gt;
&lt;p&gt;&lt;span style=&quot;color: #999999;&quot;&gt;&lt;em&gt;&lt;span style=&quot;font-size: 14px;&quot;&gt;秋分气象和农事特点：凉风习习，田间秋收、秋耕、秋种忙。&lt;/span&gt;&lt;/em&gt;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;秋分时节，凉风习习，碧空万里。&lt;/p&gt;
&lt;p&gt;秋分是二十四节气中的第十六个节气，每年阳历9月23日前后，南方的气候由这一节气起才始入秋。太阳黄经为180&amp;deg;是秋分。我国古籍《春秋繁露&amp;middot;阴阳出入上下篇》中记载：&amp;ldquo;秋分者，阴阳相半也，故昼夜均而寒暑平。&lt;/p&gt;
&lt;p&gt;&amp;rdquo;秋分这一天同春分一样，阳光几乎直射赤道，昼夜几乎相等。秋分是表征季节变化的节气。从这一天起，阳光直射位置继续由赤道向南半球推移，北半球开始昼短夜长。根据我国旧历的记载，这一天刚好是秋季九十天的一半，因而称秋分。但在天文学上规定北半球的秋天是从秋分开始的。&lt;/p&gt;
&lt;p&gt;秋分时节，长江流域及其以北的广大地区，均先后进入了秋季，日平均气温都降到了22℃以下。北方冷气团开始具有一定的势力，大部分地区雨季已经结束，凉风习习，碧空万里，风和日丽，秋高气爽，丹桂飘香，蟹肥菊黄。秋分是气候宜人的时节，也是农业生产上重要的节气。秋分后太阳直射的位置南移到南半球，北半球得到的太阳辐射逐渐减少，这个时节地面散失的热量越来越多，气温降低的速度也越来越快。&lt;/p&gt;', '{"content_type":"html"}');
INSERT INTO "item" VALUES (10019, 0, 0, 7, 1633680261, 1751964288, 100, 1, 1, '81e69abb88b4ade7e9793301bb641663', ',10019,', '', '寒露菊芳的丰厚蕴藏', '', NULL, '', 'data/file/item/10019', '', '', '', '', '', '', '', '', '{"url":"","target":"_blank"}', '{"title":"","keywords":"","description":""}', '寒露时节是中国南北大地上景观差异最大、色彩最为绚丽的时间；寒露来临之时，也是枫叶飘红菊花飘香的时节；寒露菊芳，清秋多了一缕缕冷香。', '&lt;p&gt;寒露时节是中国南北大地上景观差异最大、色彩最为绚丽的时间；寒露来临之时，也是枫叶飘红菊花飘香的时节；寒露菊芳，清秋多了一缕缕冷香。&lt;/p&gt;
&lt;p&gt;&lt;img src=&quot;data/file/blog/03.png&quot; alt=&quot;&quot; /&gt;&lt;/p&gt;
&lt;p&gt;&lt;em&gt;&lt;span style=&quot;font-size: 14px; color: #808080;&quot;&gt;寒露气象和农事特点：昼暖夜凉，农田秋收、灌溉、播种忙。&lt;/span&gt;&lt;/em&gt;&lt;/p&gt;
&lt;p&gt;寒露时节，昼暖夜凉、晴空万里。&lt;/p&gt;
&lt;p&gt;寒露是二十四节气中第十七个节气，在每年阳历10月8日或9日，太阳黄经为195&amp;deg;是寒露。《月令七十二候集解》说：&amp;ldquo;九月节，露气寒冷，将凝结也。&amp;rdquo;寒露表示气温比白露时更低，地面的露水更凉，快要凝结成霜了。&lt;/p&gt;
&lt;p&gt;白露后，天气转凉，开始出现露水，到了寒露，则露水增多，并且气温将更低了。寒露以后，北方地区冷空气已经具有一定势力，我国大部分地区在冷高压控制之下，雨季基本结束。天气常常是昼暖夜凉，晴空万里，对秋季农作物收获十分有利。&lt;/p&gt;
&lt;p&gt;大部分地区的雷暴也已经消失，只有云南、四川和贵州局部地区尚可听到雷声。华北10月份降水量一般只有9月降水量的一半或者更少，西北地区则只有几毫米到20多毫米。干旱少雨往往给冬小麦的适时播种带来一些困难，这些不利因素成为旱地小麦争取高产的主要障碍。&lt;/p&gt;', '{"content_type":"html"}');
