INSERT INTO "item" VALUES (11001, 11019, 0, 11000, 0, 1728894903, 100, 1, 1, '', ',11019,11001,', '', '后台拖入页面组件一直在加载中？', '', NULL, '', 'http://192.168.31.5:8087/', '', '', '', '', '', '', '', '', '', '', '&lt;p&gt;如果您的网站首页能够正常浏览，但遇到了某些问题，这通常是因为 Nginx 还未配置伪静态规则。您可以尝试添加以下配置：
location / { try_files $uri $uri/ /index.php?$args; }&lt;/p&gt;', '', '{"summary_type":"html"}');
INSERT INTO "item" VALUES (11002, 0, 0, 11000, 0, 0, 100, 1, 1, '', '', '', '安装网站需要什么环境要求？', '', NULL, '', 'http://192.168.31.5:8087/', '', '', '', '', '', '', '', '', '', '', '&lt;p&gt;推荐使用 PHP 7.4 或更高版本，SQLite3 数据库，以及 Apache 或 Nginx 作为 WEB 服务器。若您寻求便捷的集成环境，宝塔面板是一个不错的选择。&lt;/p&gt;', '', '');
INSERT INTO "item" VALUES (11003, 0, 0, 11000, 0, 0, 100, 1, 1, '', '', '', '现在技术更新这么快，你们会经常更新系统吗？', '', NULL, '', 'http://192.168.31.5:8087/', '', '', '', '', '', '', '', '', '', '', '&lt;p&gt;当然会的。我们会定期更新网站的新功能、组件、修复 Bug 以及增强安全性等。一旦有重要更新，您登录后台后会收到一键升级的提示。&lt;/p&gt;', '', '');
INSERT INTO "item" VALUES (11004, 0, 0, 11000, 0, 0, 100, 1, 1, '', '', '', '网站托管在你们这里管理可以吗？', '', NULL, '', 'http://192.168.31.5:8087/', '', '', '', '', '', '', '', '', '', '', '&lt;p&gt;可以的。您可以选择我们已经搭建好的云建站。或者，如果您有特殊要求，请随时与我们联系。&lt;/p&gt;', '', '');
INSERT INTO "item" VALUES (11005, 0, 0, 11000, 0, 0, 100, 1, 1, '', '', '', '我的网站想添加特殊功能可以吗？', '', NULL, '', 'http://192.168.31.5:8087/', '', '', '', '', '', '', '', '', '', '', '&lt;p&gt;可以的，请联系我们并提出您的需求。&lt;/p&gt;', '', '');
INSERT INTO "item" VALUES (11006, 0, 0, 11000, 0, 0, 100, 1, 1, '', '', '', '如果使用不满意可以退款吗？', '', NULL, '', 'http://192.168.31.5:8087/', '', '', '', '', '', '', '', '', '', '', '&lt;p&gt;抱歉。我们提供免费版本，您可以使用一段时间后再决定是否购买。&lt;/p&gt;', '', '');
INSERT INTO "item" VALUES (11007, 0, 0, 11000, 0, 0, 100, 1, 1, '', '', '', '我需要的组件没有，我能提出增加吗？', '', NULL, '', 'http://192.168.31.5:8087/', '', '', '', '', '', '', '', '', '', '', '&lt;p&gt;当然可以。请在群里提出您的需求。我们将评估这一需求，若确实符合未来发展方向，我们将安排下一次的组件开发。&lt;/p&gt;', '', '');
INSERT INTO "item" VALUES (11008, 0, 0, 11000, 0, 0, 100, 1, 1, '', '', '', '我可以把旧网站的数据迁移过来吗？', '', NULL, '', 'http://192.168.31.5:8087/', '', '', '', '', '', '', '', '', '', '', '&lt;p&gt;如果您的网站是在其他平台建立的，就需要手动迁移至我们的平台了。&lt;/p&gt;', '', '');
INSERT INTO "item" VALUES (11009, 0, 0, 11000, 0, 0, 100, 1, 1, '', '', '', '我可以制作网站模板吗？', '', NULL, '', 'http://192.168.31.5:8087/', '', '', '', '', '', '', '', '', '', '', '&lt;p&gt;当然可以，但这仅适用于我们认证的会员。&lt;/p&gt;', '', '');
INSERT INTO "item" VALUES (11010, 0, 0, 11000, 0, 0, 100, 1, 1, '', '', '', '我可以自定义页面组件吗？', '', NULL, '', 'http://192.168.31.5:8087/', '', '', '', '', '', '', '', '', '', '', '&lt;p&gt;可以的。我们提供修改源代码的方式来自定义静态组件，同时也支持对网站整体样式进行定制。&lt;/p&gt;', '', '');
INSERT INTO "item" VALUES (11011, 0, 0, 11000, 0, 0, 100, 1, 1, '', '', '', '我可以在本地安装网站吗？', '', NULL, '', 'http://192.168.31.5:8087/', '', '', '', '', '', '', '', '', '', '', '&lt;p&gt;不可以啦！网站域名必须能够被互联网访问。&lt;/p&gt;', '', '');
INSERT INTO "item" VALUES (11012, 0, 0, 11000, 0, 0, 100, 1, 1, '', '', '', '免费用户有什么限制吗？', '', NULL, '', 'http://192.168.31.5:8087/', '', '', '', '', '', '', '', '', '', '', '&lt;p&gt;限制为只能创建5个页面，无法使用部分动态组件和模板等功能。&lt;/p&gt;', '', '');
INSERT INTO "item" VALUES (11013, 0, 0, 11000, 0, 0, 100, 1, 1, '', '', '', '一个域名可以安装多少个网站？', '', NULL, '', 'http://192.168.31.5:8087/', '', '', '', '', '', '', '', '', '', '', '&lt;p&gt;会员可以享受无限安装的权益，而免费用户则限于安装一次。&lt;/p&gt;', '', '');
INSERT INTO "item" VALUES (11014, 0, 0, 11000, 0, 0, 100, 1, 1, '', '', '', '我不会拼装网站怎么办？', '', NULL, '', 'http://192.168.31.5:8087/', '', '', '', '', '', '', '', '', '', '', '&lt;p&gt;您可以选择使用我们精心制作的整站模板，或者通过观看视频教程来学习相关知识。&lt;/p&gt;', '', '');
INSERT INTO "item" VALUES (11015, 0, 0, 11000, 0, 0, 100, 1, 1, '', '', '', '网站过期了我不续费可以用吗？', '', NULL, '', 'http://192.168.31.5:8087/', '', '', '', '', '', '', '', '', '', '', '&lt;p&gt;如果您的网站是部署在自己的服务器上，它将能够照常运行。但是，当您登录后台管理系统时，您将只能使用免费版本的功能。&lt;/p&gt;', '', '');
INSERT INTO "item" VALUES (11016, 0, 0, 11000, 0, 0, 100, 1, 1, '', '', '', '我在哪里购买域名和主机好呢？', '', NULL, '', 'http://192.168.31.5:8087/', '', '', '', '', '', '', '', '', '', '', '&lt;p&gt;您可以选择在腾讯云或阿里云购买服务器。如果您希望简化流程，也可以将网站托管给我们，由我们来负责管理。&lt;/p&gt;', '', '');
INSERT INTO "item" VALUES (11017, 0, 0, 11000, 0, 0, 100, 1, 1, '', '', '', '我想购买网站要怎样支付呢？', '', NULL, '', 'http://192.168.31.5:8087/', '', '', '', '', '', '', '', '', '', '', '&lt;p&gt;目前，您可以通过登录网站后台，并使用支付宝扫码的方式进行支付。&lt;/p&gt;', '', '');
INSERT INTO "item" VALUES (11018, 0, 0, 11000, 0, 0, 100, 1, 1, '', '', '', '我不懂安装，你们能帮我安装网站吗？', '', NULL, '', 'http://192.168.31.5:8087/', '', '', '', '', '', '', '', '', '', '', '&lt;p&gt;当然可以！您只需购买任意一款会员服务，并提供您的网站域名以及主机账号，或者选择我们的极速建站服务，即可享受无需等待的便捷体验。&lt;/p&gt;', '', '');
