INSERT INTO "item" VALUES (11037, 0, 0, 11014, 1756609212, 0, 100, 1, 2, '', ',11037,', '', '宋词很美·少年游', '', '', '', 'data/file/item/11037', '', '', '', '', '', '', '', '', '', '', '', '', '');
INSERT INTO "item" VALUES (11038, 11037, 0, 11014, 1756609573, 1756713979, 100, 1, 1, '', ',11037,11038,', '', '唐多令·芦叶满汀洲', '', '', '', 'data/file/item/11038', '', '', '', '', '', '', '', '', '', '', '&lt;p&gt;芦叶满汀洲，寒沙带浅流。&lt;br /&gt;二十年重过南楼。&lt;br /&gt;柳下系船犹未稳，能几日，又中秋。&lt;/p&gt;
&lt;p&gt;黄鹤断矶头，故人今在否？&lt;br /&gt;旧江山浑是新愁。&lt;br /&gt;欲买桂花同载酒，终不似，少年游。&lt;/p&gt;', '', '{"author":"刘过","era":"唐代","comment":"<p>芦苇的枯叶落满沙洲，浅浅的寒水在沙滩上无声无息地流过。二十年光阴似箭，如今我又重新登上这旧地南楼。柳树下的小舟尚未系稳，我就匆匆忙忙重回故地。因为过不了几日就是中秋。<\/p>\r\n<p>早已破烂不堪的黄鹤矶头，我的老朋友有没有来过？我眼前满目是苍凉的旧江山，又平添了无尽的绵绵新愁。想要买上桂花，带着美酒一同去水上泛舟逍遥一番。但却没有了少年时那种豪迈的意气。<\/p>","comment_en":"<p>The reed leaves cover the islet, and the shallow cold water flows silently over the beach. After twenty years, I revisit the South Tower. The boat under the willow tree is not yet securely tied, and I hurriedly return to this place. In a few days, it will be the Mid-Autumn Festival.<\/p>\r\n<p>At the broken reef of Yellow Crane Tower, are my old friends still around? The old rivers and mountains are now filled with new sorrows. I want to buy osmanthus flowers and take wine to go boating, but after all, I don''t have the traveling spirit of youth.<\/p>"}');
INSERT INTO "item" VALUES (11039, 11037, 0, 11014, 1756686672, 1756687023, 100, 1, 1, '', ',11037,11039,', '', '菩萨蛮', '', '', '', 'data/file/item/11039', '', '', '', '', '', '', '', '', '', '', '&lt;p&gt;梅花吹入谁家笛，行云半夜凝空碧。欹枕不成眠，关山人未还。&lt;/p&gt;
&lt;p&gt;声随幽怨绝，云断澄霜月。月影下重帘，轻风花满檐。&lt;/p&gt;', '', '{"author":"冯延巳","era":"五代十国","summary_type":"html","comment":"<p>梅花的香气随着谁家的笛声飘来。夜空中飘动的云彩在半夜时分凝结在碧蓝的天幕上。斜靠着枕头，却无法入睡。远在关山之外的人尚未归来。<\/p>\r\n<p>笛声带着幽怨之情渐渐消失。云彩散去，露出澄澈的霜月。月光透过重重帘幕洒落下来。轻风拂过，花瓣飘落在屋檐上。<\/p>","_more[comment":"html","comment_en":"<p>The fragrance of plum blossoms is carried by the flute music from someone&rsquo;s home. The drifting clouds congeal in the midnight azure sky. Leaning on the pillow, I cannot fall asleep, for the person beyond the mountains has yet to return.<\/p>\r\n<p>&nbsp;The music fades with a lingering sense of sorrow, as the clouds part to reveal a clear, frosty moon. The moonlight filters down through layers of curtains, and a gentle breeze fills the eaves with petals.<\/p>","_more[comment_en":"html"}');
INSERT INTO "item" VALUES (11040, 11037, 0, 11014, 1756686843, 1756687014, 100, 1, 1, '', ',11037,11040,', '', '望江南·超然台作', '', '', '', 'data/file/item/11040', '', '', '', '', '', '', '', '', '', '', '&lt;p&gt;春未老，风细柳斜斜。试上超然台上看，半壕春水一城花。烟雨暗千家。&lt;/p&gt;
&lt;p&gt;寒食后，酒醒却咨嗟。休对故人思故国，且将新火试新茶。诗酒趁年华。&lt;/p&gt;', '', '{"author":"苏轼","era":"宋代","summary_type":"html","comment":"<p>春天尚未过去，微风轻拂，柳枝随风斜斜飘动。登上超然台远眺，护城河内春水荡漾，满城繁花似锦，烟雨蒙蒙，千家万户都笼罩在迷蒙的雨色之中。<\/p>\r\n<p>寒食节过后，酒醒时分，词人不禁发出叹息。他劝自己不要再在老朋友面前提起故乡，姑且点上新火来烹煮一杯刚采的新茶，趁着年华未老，尽情吟诗饮酒。<\/p>","_more[comment":"html","comment_en":"<p>Spring is not yet old, with a gentle breeze and slanting willows. I climb up the Transcendence Terrace to look around: half the moat is filled with spring water, and the whole city is in bloom. The misty rain darkens a thousand homes.<\/p>\r\n<p>After the Cold Food Festival, I sober up and sigh. Don''t think of the old country with old friends; instead, light the new fire to brew the new tea. Enjoy poetry and wine while we are still young.<\/p>","_more[comment_en":"html"}');
INSERT INTO "item" VALUES (11041, 11037, 0, 11014, 1756686897, 1756687007, 100, 1, 1, '', ',11037,11041,', '', '南乡子·送客过余溪', '', '', '', 'data/file/item/11041', '', '', '', '', '', '', '', '', '', '', '&lt;p&gt;相并细腰身。时样宫妆一样新。曲项胡琴鱼尾拨，离人。入塞弦声水上闻。&lt;/p&gt;
&lt;p&gt;天碧染衣巾。血色轻罗碎摺裙。百卉已随霜女妒，东君。暗折双花借小春。&lt;/p&gt;', '', '{"author":"张先","era":"宋代","summary_type":"html","comment":"<p>这首词描绘了一位女子的美貌与才情。词中提到女子的身材纤细，妆容时尚，与他人一样美丽。她弹奏着胡琴，琴声如离人之叹，仿佛从塞外传来，回荡在水上。女子的衣着华丽，衣巾被蓝天映衬得格外鲜艳，裙摆如血色轻罗般飘逸。尽管霜女妒忌，但春天的使者东君却暗中为她折取了双花，增添了几分春意。<\/p>","_more[comment":"html","comment_en":"<p>Side by side with a slender waist. The fashionably styled palace makeup is all new. The curved-neck Huqin with its fish-tail plectrum, for the parting ones. The sound of the strings entering the frontier is heard over the water.<\/p>\r\n<p>The azure sky dyes the scarf and kerchief. The blood-red light gauze skirt with scattered pleats. All flowers have been envied by the Frost Maiden, and the Lord of Spring. Secretly breaks two flowers to borrow from the early spring.<\/p>","_more[comment_en":"html"}');
INSERT INTO "item" VALUES (11042, 11037, 0, 11014, 1756686936, 1756686998, 100, 1, 1, '', ',11037,11042,', '', '南歌子', '', '', '', 'data/file/item/11042', '', '', '', '', '', '', '', '', '', '', '&lt;p&gt;疏雨池塘见，微风襟袖知。阴阴夏木啭黄鹂，何处飞来白鹭立移时。&lt;/p&gt;
&lt;p&gt;易醉扶头酒，难逢敌手棋。日长偏与睡相宜，睡起芭蕉叶上自题诗。&lt;/p&gt;', '', '{"author":"贺铸","era":"宋代","summary_type":"html","comment":"<p>稀疏的雨点落在池塘里，水面上泛起涟漪。轻风拂来，微微吹动衣袖。夏天的树长满了浓密的叶子，树荫中响起黄鹂婉转的啼叫声。不知从何处飞来一只白鹭，独立池塘，已经很久。喝扶头酒很容易让人醉，但下棋时却难逢对手。漫长的夏日，最适合睡觉。睡醒后，一个人在芭蕉叶子上百无聊赖地写着诗。<\/p>","_more[comment":"html","comment_en":"<p>Sparse rain is seen over the pond, a gentle breeze is felt on my sleeves. In the dense summer woods, the oriole trills, where has the white heron flown from, standing there for a while.<\/p>\r\n<p>It&rsquo;s easy to get drunk on strong wine, hard to find a worthy opponent in chess. The long day is especially suitable for sleep, upon waking, I write poems on the banana leaves.<\/p>","_more[comment_en":"html"}');
INSERT INTO "item" VALUES (11043, 11037, 0, 11014, 1756686985, 0, 100, 1, 1, '', ',11037,11043,', '', '水调歌头·黄州快哉亭赠张偓佺', '', '', '', 'data/file/item/11043', '', '', '', '', '', '', '', '', '', '', '&lt;p&gt;落日绣帘卷，亭下水连空。知君为我新作，窗户湿青红。长记平山堂上，欹枕江南烟雨，杳杳没孤鸿。认得醉翁语，山色有无中。&lt;/p&gt;
&lt;p&gt;一千顷，都镜净，倒碧峰。忽然浪起，掀舞一叶白头翁。堪笑兰台公子，未解庄生天籁，刚道有雌雄。一点浩然气，千里快哉风。&lt;/p&gt;', '', '{"author":"苏轼","era":"宋代","summary_type":"html","comment":"<p>夕阳西下，我卷起绣花的帘子，看到亭子下面的江水与天空相连。我知道你（张偓佺）为我新建了这座亭子，新漆的窗户还带着湿润的青红颜色。我常常回忆起在平山堂上，斜靠在枕上，欣赏着江南的烟雨，看着天边的孤鸿渐渐消失在远方。我认得这是醉翁（欧阳修）曾经说过的意境，山色在有无之间，若隐若现。<\/p>\r\n<p>江面广阔，如同一面巨大的镜子，清澈透明，倒映着碧绿的山峰。忽然间，江面上掀起波浪，一位白发老翁在浪尖上舞动。可笑那兰台公子（宋玉），没有理解庄子所说的&ldquo;天籁&rdquo;的真正含义，却硬要说风有雌雄之分。只要内心保持正直、刚强的浩然之气，就能在广阔天地间感受到令人舒畅、惬意的清风，享受自由自在的生活。<\/p>","_more[comment":"html","comment_en":"<p>The setting sun rolls up the embroidered curtains, and beneath the pavilion, the water seems to merge with the sky. Knowing that you have built this place anew for me, the windows are still wet with fresh vermilion and green. I always recall the time on the Ping Mountain Hall, where I lay on my pillow, watching the misty rain over the Jiangnan region, and the distant solitary wild goose gradually disappears from sight. I recognize the words of the drunken old man, \"The mountains appear and disappear in the mist.\"<\/p>\r\n<p>A thousand acres stretch out before me, as clear as a mirror, with the inverted reflection of green peaks. Suddenly, waves rise, and a white-haired old man dances in a single boat. It''s laughable that the young master of the Orchid Terrace doesn''t understand the natural sounds described by Zhuangzi, and insists on distinguishing between male and female winds. With a bit of righteous spirit, one can enjoy the refreshing breeze that travels a thousand miles.<\/p>","_more[comment_en":"html"}');
